import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.B4hAkGey.js";const g=JSON.parse('{"title":"15.2 进阶应用：延迟梯度、卡尔曼滤波与状态机","description":"","frontmatter":{},"headers":[],"relativePath":"guide/15-handwritten-gcc/advanced.md","filePath":"guide/15-handwritten-gcc/advanced.md","lastUpdated":1792683941000}'),p={name:"guide/15-handwritten-gcc/advanced.md"};function l(i,a,d,r,o,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="_15-2-进阶应用-延迟梯度、卡尔曼滤波与状态机" tabindex="-1">15.2 进阶应用：延迟梯度、卡尔曼滤波与状态机 <a class="header-anchor" href="#_15-2-进阶应用-延迟梯度、卡尔曼滤波与状态机" aria-label="Permalink to &quot;15.2 进阶应用：延迟梯度、卡尔曼滤波与状态机&quot;">​</a></h1><blockquote><p>GCC 的精妙之处在于：它不把「延迟高」当拥塞，而是把「延迟在变大」当拥塞。这一章我们拆开它的四个核心组件，看它们如何协同工作。</p></blockquote><hr><h2 id="_15-2-1-arrival-time-filter-分组到达间隔-vs-发送间隔" tabindex="-1">15.2.1 Arrival-time Filter：分组到达间隔 vs 发送间隔 <a class="header-anchor" href="#_15-2-1-arrival-time-filter-分组到达间隔-vs-发送间隔" aria-label="Permalink to &quot;15.2.1 Arrival-time Filter：分组到达间隔 vs 发送间隔&quot;">​</a></h2><p>GCC 的输入不是单个包的延迟，而是<strong>两组包之间的相对关系</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送端                          接收端</span></span>
<span class="line"><span>  │                               │</span></span>
<span class="line"><span>  │  T1: 发出包组 A (1000 bytes)  │</span></span>
<span class="line"><span>  │ ────────────────────────────&gt; │  A1: 到达</span></span>
<span class="line"><span>  │                               │</span></span>
<span class="line"><span>  │  T2: 发出包组 B (1000 bytes)  │</span></span>
<span class="line"><span>  │ ────────────────────────────&gt; │  A2: 到达</span></span>
<span class="line"><span>  │                               │</span></span></code></pre></div><p>定义两个时间差：</p><table tabindex="0"><thead><tr><th>符号</th><th>含义</th><th>公式</th></tr></thead><tbody><tr><td><code>send_delta</code></td><td>两组包的发送间隔</td><td><code>T2 - T1</code></td></tr><tr><td><code>arrival_delta</code></td><td>两组包的到达间隔</td><td><code>A2 - A1</code></td></tr></tbody></table><p>如果网络空闲，接收端应该<strong>原样复制</strong>发送端的时间模式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>send_delta ≈ arrival_delta   →   一切正常</span></span></code></pre></div><p>如果网络拥塞，包在路由器里排队，后到的包要等前面的包发完：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arrival_delta &gt; send_delta   →   队列在堆积</span></span></code></pre></div><hr><h2 id="_15-2-2-delay-gradient-延迟梯度的定义" tabindex="-1">15.2.2 Delay Gradient：延迟梯度的定义 <a class="header-anchor" href="#_15-2-2-delay-gradient-延迟梯度的定义" aria-label="Permalink to &quot;15.2.2 Delay Gradient：延迟梯度的定义&quot;">​</a></h2><p><strong>延迟梯度（Delay Gradient）</strong> 就是两者的差值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>delay_gradient = arrival_delta - send_delta</span></span></code></pre></div><table tabindex="0"><thead><tr><th>场景</th><th>delay_gradient</th><th>含义</th></tr></thead><tbody><tr><td>队列稳定</td><td>≈ 0</td><td>延迟不变，链路刚好跑满</td></tr><tr><td>队列变长</td><td>&gt; 0</td><td>延迟在增加，即将拥塞</td></tr><tr><td>队列变短</td><td>&lt; 0</td><td>延迟在减小，链路易空闲</td></tr></tbody></table><p>注意 GCC 关注的是<strong>变化趋势</strong>而不是绝对值：</p><ul><li>延迟 200ms 但稳定 → 不一定拥塞（可能是跨洲链路）</li><li>延迟 20ms 但每秒涨 10ms → 即将拥塞</li></ul><hr><h2 id="_15-2-3-trendline-filter-用线性回归平滑梯度" tabindex="-1">15.2.3 Trendline Filter：用线性回归平滑梯度 <a class="header-anchor" href="#_15-2-3-trendline-filter-用线性回归平滑梯度" aria-label="Permalink to &quot;15.2.3 Trendline Filter：用线性回归平滑梯度&quot;">​</a></h2><p>原始 delay gradient 非常 noisy（有抖动、有乱序），不能直接用来调码率。GCC 用<strong>最小二乘线性回归（Least Squares Linear Regression）</strong> 拟合最近 N 个样本的趋势。</p><h3 id="算法" tabindex="-1">算法 <a class="header-anchor" href="#算法" aria-label="Permalink to &quot;算法&quot;">​</a></h3><p>对最近 20 个样本 <code>(x_i, y_i)</code>，其中 <code>x_i</code> 是时间，<code>y_i</code> 是 delay gradient，拟合直线：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y = a + b·x</span></span></code></pre></div><p>最小化误差平方和：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>min Σ (y_i - a - b·x_i)²</span></span></code></pre></div><p>解得斜率：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        n·Σ(x_i·y_i) - Σx_i·Σy_i</span></span>
<span class="line"><span>b = ─────────────────────────────</span></span>
<span class="line"><span>        n·Σx_i² - (Σx_i)²</span></span></code></pre></div><h3 id="为什么是斜率而不是均值" tabindex="-1">为什么是斜率而不是均值？ <a class="header-anchor" href="#为什么是斜率而不是均值" aria-label="Permalink to &quot;为什么是斜率而不是均值？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>样本值</span></span>
<span class="line"><span>  ↑</span></span>
<span class="line"><span>  │    ●</span></span>
<span class="line"><span>  │   ● ●        ●</span></span>
<span class="line"><span>  │  ●   ●      ● ●</span></span>
<span class="line"><span>  │ ●     ●    ●   ●</span></span>
<span class="line"><span>  │        ●  ●     ●</span></span>
<span class="line"><span>  │         ●        ●</span></span>
<span class="line"><span>  └────────────────────→ 时间</span></span>
<span class="line"><span>         ↑</span></span>
<span class="line"><span>    斜率 b &gt; 0：虽然当前值不高，但趋势在涨</span></span></code></pre></div><ul><li><strong>均值</strong>告诉你「现在延迟高不高」</li><li><strong>斜率</strong>告诉你「延迟在变好还是变坏」</li></ul><p>GCC 要的是<strong>预测</strong>，所以用斜率。</p><hr><h2 id="_15-2-4-overuse-detector-阈值自适应与状态机" tabindex="-1">15.2.4 Overuse Detector：阈值自适应与状态机 <a class="header-anchor" href="#_15-2-4-overuse-detector-阈值自适应与状态机" aria-label="Permalink to &quot;15.2.4 Overuse Detector：阈值自适应与状态机&quot;">​</a></h2><p>得到 trendline 斜率后，Overuse Detector 判断当前链路状态。</p><h3 id="三态状态机" tabindex="-1">三态状态机 <a class="header-anchor" href="#三态状态机" aria-label="Permalink to &quot;三态状态机&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         ┌─────────┐</span></span>
<span class="line"><span>         │  Normal │</span></span>
<span class="line"><span>         └────┬────┘</span></span>
<span class="line"><span>              │ slope &gt; threshold 持续一段时间</span></span>
<span class="line"><span>              ▼</span></span>
<span class="line"><span>         ┌─────────┐</span></span>
<span class="line"><span>    ┌───│ Overuse │◄──┐</span></span>
<span class="line"><span>    │    └────┬────┘   │</span></span>
<span class="line"><span>    │         │ slope &lt; -threshold</span></span>
<span class="line"><span>    │         ▼        │</span></span>
<span class="line"><span>    │    ┌─────────┐   │</span></span>
<span class="line"><span>    └───│ Underuse│───┘</span></span>
<span class="line"><span>         └─────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>控制器动作</th></tr></thead><tbody><tr><td><strong>Normal</strong></td><td>链路刚好跑满</td><td>保持或微调</td></tr><tr><td><strong>Overuse</strong></td><td>队列在堆积</td><td><strong>乘性减少</strong>码率</td></tr><tr><td><strong>Underuse</strong></td><td>队列在排空</td><td><strong>加性增加</strong>码率</td></tr></tbody></table><h3 id="阈值自适应-adaptive-threshold" tabindex="-1">阈值自适应（Adaptive Threshold） <a class="header-anchor" href="#阈值自适应-adaptive-threshold" aria-label="Permalink to &quot;阈值自适应（Adaptive Threshold）&quot;">​</a></h3><p>固定阈值的问题：</p><ul><li>阈值太小 → 一点抖动就误报 overuse</li><li>阈值太大 → 真拥塞了检测不出来</li></ul><p>GCC 的解法是<strong>让阈值自己动</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if |slope| &gt; threshold:</span></span>
<span class="line"><span>    threshold += K · |slope| · Δt    # 放宽</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    threshold -= K · |slope| · Δt    # 收紧</span></span></code></pre></div><p>这样当网络抖动大时，阈值自动放宽；网络稳定时，阈值自动收紧。</p><hr><h2 id="_15-2-5-aimd-controller-加性增-乘性减" tabindex="-1">15.2.5 AIMD Controller：加性增 / 乘性减 <a class="header-anchor" href="#_15-2-5-aimd-controller-加性增-乘性减" aria-label="Permalink to &quot;15.2.5 AIMD Controller：加性增 / 乘性减&quot;">​</a></h2><p>这是 TCP 的经典策略，GCC 在延迟域做了同样的事。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>码率</span></span>
<span class="line"><span>  ↑</span></span>
<span class="line"><span>  │      /\\</span></span>
<span class="line"><span>  │     /  \\</span></span>
<span class="line"><span>  │    /    \\        ← Overuse 触发</span></span>
<span class="line"><span>  │   /      \\      /</span></span>
<span class="line"><span>  │  /        \\    /</span></span>
<span class="line"><span>  │ /          \\  /</span></span>
<span class="line"><span>  │/            \\/</span></span>
<span class="line"><span>  └────────────────→ 时间</span></span>
<span class="line"><span>    加性增加   乘性减少</span></span>
<span class="line"><span>    (慢)      (快)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>状态</th><th>动作</th><th>公式</th><th>为什么</th></tr></thead><tbody><tr><td>Underuse / Normal</td><td>加性增加</td><td><code>R += step</code></td><td>慢慢试探，别冲过头</td></tr><tr><td>Overuse</td><td>乘性减少</td><td><code>R *= factor</code></td><td>快速刹车，防止雪崩</td></tr></tbody></table><p>典型参数（WebRTC 默认）：</p><ul><li>加性步长：<code>+5 ~ +50 kbps</code>（每次反馈）</li><li>乘性因子：<code>0.85</code>（砍 15%）</li><li>最小码率：<code>100 kbps</code>（保证基本通话）</li><li>最大码率：<code>5 Mbps</code>（受限于编码器能力）</li></ul><hr><h2 id="_15-2-6-目标码率收敛与边界" tabindex="-1">15.2.6 目标码率收敛与边界 <a class="header-anchor" href="#_15-2-6-目标码率收敛与边界" aria-label="Permalink to &quot;15.2.6 目标码率收敛与边界&quot;">​</a></h2><p>AIMD 的收敛过程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>码率</span></span>
<span class="line"><span>  ↑</span></span>
<span class="line"><span>  │                                    ╭──── 最大码率(5 Mbps)</span></span>
<span class="line"><span>  │                                   /</span></span>
<span class="line"><span>  │                  ╭──╮            /</span></span>
<span class="line"><span>  │                 /    \\          /</span></span>
<span class="line"><span>  │        ╭──╮    /      \\    ╭───╯</span></span>
<span class="line"><span>  │       /    \\  /        \\  /</span></span>
<span class="line"><span>  │  ╭───╯      \\/          \\/</span></span>
<span class="line"><span>  │  /</span></span>
<span class="line"><span>  │ /</span></span>
<span class="line"><span>  └────────────────────────────────→ 时间</span></span>
<span class="line"><span>    ↑        ↑        ↑        ↑</span></span>
<span class="line"><span>  初始    Overuse   收敛    容量变化</span></span>
<span class="line"><span>  探测    急刹车    稳定    重新收敛</span></span></code></pre></div><p>边界处理：</p><ul><li><strong>撞下限</strong>：低于 100 kbps 时不再降（否则画面全黑）</li><li><strong>撞上限</strong>：高于 5 Mbps 时不再加（编码器编不动）</li></ul><hr><h2 id="_15-2-7-卡尔曼滤波在原始-gcc-中的角色" tabindex="-1">15.2.7 卡尔曼滤波在原始 GCC 中的角色 <a class="header-anchor" href="#_15-2-7-卡尔曼滤波在原始-gcc-中的角色" aria-label="Permalink to &quot;15.2.7 卡尔曼滤波在原始 GCC 中的角色&quot;">​</a></h2><p>2012 年的原始 GCC 论文用的不是 Trendline Filter，而是<strong>卡尔曼滤波（Kalman Filter）</strong>。</p><h3 id="卡尔曼滤波版本" tabindex="-1">卡尔曼滤波版本 <a class="header-anchor" href="#卡尔曼滤波版本" aria-label="Permalink to &quot;卡尔曼滤波版本&quot;">​</a></h3><p>把延迟梯度建模为一个线性系统：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>状态方程：  x_k = x_{k-1} + w      (w 是过程噪声)</span></span>
<span class="line"><span>观测方程：  z_k = x_k + v          (v 是观测噪声)</span></span></code></pre></div><p>通过递归的「预测-更新」循环，估计出<strong>最优的当前梯度值</strong>。</p><h3 id="为什么被-trendline-取代" tabindex="-1">为什么被 Trendline 取代？ <a class="header-anchor" href="#为什么被-trendline-取代" aria-label="Permalink to &quot;为什么被 Trendline 取代？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>卡尔曼滤波</th><th>Trendline Filter</th></tr></thead><tbody><tr><td>计算复杂度</td><td>高（矩阵运算）</td><td>低（纯标量）</td></tr><tr><td>参数调优</td><td>难（Q/R 矩阵）</td><td>简单（窗口大小）</td></tr><tr><td>对突发响应</td><td>慢（惯性大）</td><td>快（窗口滑动）</td></tr><tr><td>可解释性</td><td>黑盒</td><td>白盒（线性回归）</td></tr></tbody></table><p>2016 年后，WebRTC 全面切换到 Trendline Filter。卡尔曼滤波作为历史背景了解即可。</p><hr><h2 id="_15-2-8-小结" tabindex="-1">15.2.8 小结 <a class="header-anchor" href="#_15-2-8-小结" aria-label="Permalink to &quot;15.2.8 小结&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入: 包到达时间</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Arrival-time Filter  →  计算 delay_gradient = arrival_delta - send_delta</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Trendline Filter     →  最小二乘回归，输出斜率 slope</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Overuse Detector     →  阈值比较 + 状态机，输出 Normal/Overuse/Underuse</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>AIMD Controller      →  加性增 / 乘性减，输出目标码率</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>编码器                →  按目标码率编码视频</span></span></code></pre></div><p>四个组件各司其职，共同完成「在延迟爆炸前踩刹车」的任务。</p><p>→ <a href="./practice">15.3 实战案例：Node.js 手写简化版 GCC</a></p>`,73)])])}const b=s(p,[["render",l]]);export{g as __pageData,b as default};
